75	/// Public operator surface used by Qwen3.5-local benches.
76	pub mod runtime_ops {
77	    pub use crate::ops::gated_delta_rule_prefill_chunkwise_into;
78	    pub use crate::ops::rms_norm_batch_offset_into;
79	    pub use crate::ops::rms_norm_offset_into;
80	}
