82	/// Scheduler policy for balancing Qwen3.5 prefill work against active decode.
83	#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
84	pub enum Qwen35SchedulerPolicy {
85	    /// Preserve the fixed chunked-prefill behavior.
86	    #[default]
87	    Off,
88	    /// Adapt per scheduler tick based on active decode and prefill pressure.
89	    Auto,
90	}
91	
92	/// How Qwen3.5 handles a prefill chunk that arrives while decode is active.
93	#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
94	pub enum Qwen35DecodeOverlap {
95	    /// Preserve the serial Unified prefill-then-decode path.
96	    #[default]
97	    Off,
98	    /// Run prefill on a second CUDA stream while decode uses the model stream.
99	    SharedSm,
100	}
101	
102	/// TP decode runs CUDA Graphs when `cuda_graph` is set AND the rank-local
103	/// decode GQA group has a compiled kernel (`tp-design.md` P2c gate); otherwise
104	/// TP keeps the batched eager path.
105	pub fn start_engine(
106	    model_path: &Path,
107	    options: EngineLoadOptions,
108	    max_batch: usize,
109	    max_prefill_tokens: usize,
110	) -> Result<Engine> {
111	    start_engine_with_capacity_and_policy(
112	        model_path,
113	        options,
114	        max_batch,
115	        max_prefill_tokens,
116	        Qwen35SchedulerPolicy::Off,
117	        0,
118	    )
119	}
