        let err = options.device_ordinals().unwrap_err().to_string();
        assert!(err.contains("tp_size must be >= 1"));
    }

    #[test]
    fn scheduler_policy_defaults_to_off() {
        assert_eq!(Qwen35SchedulerPolicy::default(), Qwen35SchedulerPolicy::Off);
    }

