13	#[allow(clippy::too_many_arguments)]
14	pub(crate) fn gated_delta_rule_decode_vec_into(
15	    ctx: &DeviceContext,
16	    qkv: &DeviceVec,
17	    b_proj: &DeviceVec,
18	    a_proj: &DeviceVec,
19	    dt_bias: &DeviceVec,
20	    a_log: &CudaSlice<f32>,
21	    state: &mut CudaSlice<f32>,
22	    output: &mut DeviceVec,
23	    num_key_heads: usize,
24	    num_value_heads: usize,
25	    key_dim: usize,
26	    val_dim: usize,
27	) {
28	    let (qkv_ptr, _gq) = qkv.data.device_ptr(&ctx.stream);
29	    let (b_ptr, _gb) = b_proj.data.device_ptr(&ctx.stream);
30	    let (a_ptr, _ga) = a_proj.data.device_ptr(&ctx.stream);
31	    let (dt_ptr, _gdt) = dt_bias.data.device_ptr(&ctx.stream);
32	    let (alog_ptr, _gal) = a_log.device_ptr(&ctx.stream);
33	    let (s_ptr, _gs) = state.device_ptr_mut(&ctx.stream);
34	    let (o_ptr, _go) = output.data.device_ptr_mut(&ctx.stream);
35	
36	    unsafe {
37	        ffi::gated_delta_rule_decode_cuda(
38	            qkv_ptr as *const ffi::Half,
39	            b_ptr as *const ffi::Half,
40	            a_ptr as *const ffi::Half,
41	            dt_ptr as *const ffi::Half,
42	            alog_ptr as *const f32,
43	            s_ptr as *mut f32,
44	            o_ptr as *mut ffi::Half,
45	            num_key_heads as i32,
46	            num_value_heads as i32,
47	            key_dim as i32,
48	            val_dim as i32,
49	            ctx.stream.cu_stream(),
50	        );
51	    }
52	}
