54	/// Causal depthwise conv1d prefill over a HiddenStates batch.
55	#[allow(clippy::too_many_arguments)]
56	pub(crate) fn conv1d_prefill_batch_into(
57	    ctx: &DeviceContext,
58	    x_seq: &HiddenStates,
59	    conv_weight: &DeviceVec,
60	    conv_state: &mut DeviceVec,
61	    out_seq: &mut HiddenStates,
62	    kernel_size: usize,
63	) {
64	    let num_channels = x_seq.hidden_dim;
65	    assert_eq!(out_seq.hidden_dim, num_channels);
66	    assert_eq!(out_seq.seq_len, x_seq.seq_len);
67	    assert_eq!(conv_weight.len, num_channels * kernel_size);
68	    assert_eq!(conv_state.len, num_channels * (kernel_size - 1));
69	
70	    let (x_ptr, _gx) = x_seq.data.device_ptr(&ctx.stream);
71	    let (w_ptr, _gw) = conv_weight.data.device_ptr(&ctx.stream);
72	    let (s_ptr, _gs) = conv_state.data.device_ptr_mut(&ctx.stream);
73	    let (o_ptr, _go) = out_seq.data.device_ptr_mut(&ctx.stream);
74	
75	    unsafe {
76	        ffi::conv1d_prefill_cuda(
77	            x_ptr as *const ffi::Half,
78	            w_ptr as *const ffi::Half,
79	            s_ptr as *mut ffi::Half,
80	            o_ptr as *mut ffi::Half,
81	            num_channels as i32,
82	            x_seq.seq_len as i32,
83	            kernel_size as i32,
84	            ctx.stream.cu_stream(),
85	        );
86	    }
87	}
