91	    ctx: &DeviceContext,
92	    qkv: &HiddenStates,
93	    b_proj: &HiddenStates,
94	    a_proj: &HiddenStates,
95	    dt_bias: &DeviceVec,
96	    a_log: &CudaSlice<f32>,
97	    q_out: &mut HiddenStates,
98	    k_out: &mut HiddenStates,
99	    v_out: &mut HiddenStates,
100	    g_out: &mut CudaSlice<f32>,
101	    beta_out: &mut CudaSlice<f32>,
102	    num_key_heads: usize,
103	    num_value_heads: usize,
104	) -> Result<()> {
105	    let (qkv_ptr, _gqkv) = qkv.data.device_ptr(&ctx.stream);
106	    let (b_ptr, _gb) = b_proj.data.device_ptr(&ctx.stream);
107	    let (a_ptr, _ga) = a_proj.data.device_ptr(&ctx.stream);
108	    let (dt_ptr, _gdt) = dt_bias.data.device_ptr(&ctx.stream);
109	    let (alog_ptr, _gal) = a_log.device_ptr(&ctx.stream);
110	    let (q_out_ptr, _gqo) = q_out.data.device_ptr_mut(&ctx.stream);
111	    let (k_out_ptr, _gko) = k_out.data.device_ptr_mut(&ctx.stream);
112	    let (v_out_ptr, _gvo) = v_out.data.device_ptr_mut(&ctx.stream);
113	    let (g_out_ptr, _ggo) = g_out.device_ptr_mut(&ctx.stream);
114	    let (beta_out_ptr, _gbetao) = beta_out.device_ptr_mut(&ctx.stream);
115	
116	    let result = unsafe {
117	        ffi::gated_delta_rule_prefill_chunk_prepare_cuda(
118	            qkv_ptr as *const ffi::Half,
119	            b_ptr as *const ffi::Half,
120	            a_ptr as *const ffi::Half,
121	            dt_ptr as *const ffi::Half,
122	            alog_ptr as *const f32,
123	            q_out_ptr as *mut ffi::Half,
124	            k_out_ptr as *mut ffi::Half,
125	            v_out_ptr as *mut ffi::Half,
126	            g_out_ptr as *mut f32,
127	            beta_out_ptr as *mut f32,
128	            num_key_heads as i32,
129	            num_value_heads as i32,
130	            qkv.hidden_dim as i32,
131	            qkv.seq_len as i32,
132	            ctx.stream.cu_stream(),
