87	    fn new(slot_count: usize) -> Self {
88	        Self {
89	            entries: HashMap::with_capacity(slot_count),
90	            free_slots: (0..slot_count).rev().collect(),
91	            slot_count,
92	            clock: 0,
93	        }
94	    }
