103	        self.slot_count
104	    }
105	
106	    /// Advance the non-zero logical clock used by the LRU policy.
107	    fn tick(&mut self) -> u64 {
108	        self.clock = self.clock.wrapping_add(1).max(1);
109	        self.clock
110	    }
