35	impl AsyncPrefillOutput {
36	    pub(super) fn is_ready(&mut self) -> bool {
37	        match unsafe { sys::cuEventQuery(self.done.cu_event()) } {
38	            sys::CUresult::CUDA_SUCCESS => {
39	                self.completed = true;
40	                true
41	            }
42	            sys::CUresult::CUDA_ERROR_NOT_READY => false,
43	            err => fatal_cuda_lifecycle(&format!(
44	                "query Qwen3.5 async prefill event failed: {err:?}"
45	            )),
46	        }
47	    }
48	
49	    pub(super) fn into_logits(mut self) -> HiddenStates {
50	        if !self.completed {
51	            if let Err(err) = self.done.synchronize() {
52	                fatal_cuda_lifecycle(&format!("wait for Qwen3.5 async prefill failed: {err}"));
53	            }
54	            self.completed = true;
55	        }
56	        self.logits
57	            .take()
58	            .expect("async prefill logits must be consumed exactly once")
59	    }
60	}
