63	    fn drop(&mut self) {
64	        if self.completed {
65	            return;
66	        }
67	        if let Err(err) = self.stream.synchronize() {
68	            fatal_cuda_lifecycle(&format!(
69	                "drain Qwen3.5 async prefill during cleanup failed: {err}"
70	            ));
71	        }
72	    }
73	}
